//! 🧪️ The resident formatter keeps the original source, owner and paid publication across an interrupted reply.
use semio_framework_value_paged_text::{self as value,ErasedSnapshotRetirement};
use value::{OriginalConstructionAuthority,OriginalConstructionRecipient,OriginalConstructionGrant,OriginalConstructionGrantComplete,OriginalConstructionAccept,OriginalConstructionAcceptComplete,OriginalWorkAuthority,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete,RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,ValueError};
use value::paged_text::{PagedText,PagedTextEncodeFrame,PagedTextReadStep};
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_retirement::retirement::RetireOwned;
use std::panic::{catch_unwind,AssertUnwindSafe};

#[path="native-rig.rs"] mod rig;
use rig::{Work,Physical,grant,source,close_source,close_text,close_encode_failure,encode_turn,decode_turn,close_encode_frame,close_decode_frame,close_owned_failure};

#[test]
fn recorded_grant_resumes_the_original_formatter_and_paid_publication(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../📋️list/🧪️tests/🧫️fixtures/🏷️formatted-exact-extent.json")).unwrap();let body="x".repeat(law["payloadBytes"].as_u64().unwrap()as usize);let expected=format!("Set label to {body}");assert_eq!(expected.len(),law["expectedEnBytes"].as_u64().unwrap()as usize);let original=source(body);
 let mut physical=OriginalConstructionAuthority::new(Physical{interrupt:true,submitted:Default::default()});let mut work=OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=value::NativeEncodeControl::new(65536,&mut callback);let mut output=None;
 let mut frame=PagedTextEncodeFrame::<16384>::formatter(&mut output,16384,"Set label to ","").unwrap();let demand=frame.demand(original.borrow()).unwrap();let g=grant(demand);
 let interrupted=catch_unwind(AssertUnwindSafe(||physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap()));assert!(interrupted.is_err());assert_eq!(frame.demand(original.borrow()).unwrap(),demand);
 let mut completed=false;for _ in 0..100000{let d=frame.demand(original.borrow()).unwrap();let g=grant(d);let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();match turn.result{Ok(PagedTextReadStep::Complete(_))=>{completed=true;break},Ok(PagedTextReadStep::Pending|PagedTextReadStep::Progress(_))=>{},Ok(PagedTextReadStep::Denied)=>panic!("fully funded text was denied"),Err(_)=>panic!("original text action refused")}}assert!(completed);
 frame.begin_close();for _ in 0..10000{if frame.terminal_is_empty(){break}let d=frame.close_demand(4096).unwrap();let g=grant(d);let work=frame.close_work_demand(4096).unwrap();let mut actual=None;let turn=frame.close_step(&mut RetainedAllocationEffect::new(g,work,&mut actual));let progress=turn.result.unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,progress.retained_capacity_bytes)}}assert!(frame.terminal_is_empty());drop(frame);
 let text=output.take().expect("funded publication retained the output");assert!(text.borrow().unwrap().bytes().eq(expected.bytes()));assert_eq!(text.allocated_bytes(),control.owned_bytes());close_text(text);drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());close_source(original);
}

#[test]
fn intrinsic_formatter_publishes_only_the_original_selected_cell(){
 use value::paged_text::InlineTextBuffer;
 let original=source("short".to_owned());let mut physical=OriginalConstructionAuthority::new(Physical{interrupt:false,submitted:Default::default()});let mut work=OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=value::NativeEncodeControl::new(4096,&mut callback);let mut output=None;let mut inline:Option<InlineTextBuffer>=None;let mut frame=PagedTextEncodeFrame::<1024>::formatter_inline(&mut output,&mut inline,1024,"Set label to ","").unwrap();
 let mut done=false;for _ in 0..1000{let g=grant(frame.demand(original.borrow()).unwrap());let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();match turn.result{Ok(PagedTextReadStep::Complete(_))=>{done=true;break},Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},_=>panic!("intrinsic formatter refused its admitted original turn")}}assert!(done);frame.begin_close();for _ in 0..10000{if frame.terminal_is_empty(){break}let g=grant(frame.close_demand(4096).unwrap());let units=frame.close_work_demand(4096).unwrap();let mut actual=None;let turn=frame.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual));let progress=turn.result.unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,progress.retained_capacity_bytes)}}assert!(frame.terminal_is_empty());drop(frame);assert!(output.is_none());let mut cell=inline.take().expect("actual intrinsic owner was published");assert_eq!(cell.borrow().unwrap(),"Set label to short");assert!(cell.close_one(1));assert!(cell.terminal_is_empty());drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());close_source(original);
}
#[test]
fn decoder_publishes_the_actual_owner_after_separate_funding(){
 use value::paged_text::PagedTextDecodeFrame;
 let original=source("Grüße".to_owned());let mut physical=OriginalConstructionAuthority::new(Physical{interrupt:false,submitted:Default::default()});let mut work=OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=value::NativeDecodeControl::new(4096,&mut callback);let mut output=None;let mut frame=PagedTextDecodeFrame::<1024>::new(&mut output).unwrap();
 let mut done=false;for _ in 0..1000{let g=grant(frame.demand(original.borrow()).unwrap());let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();match turn.result{Ok(PagedTextReadStep::Complete(_))=>{done=true;break},Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},_=>panic!("decoder refused its admitted original turn")}}assert!(done);frame.begin_close();for _ in 0..10000{if frame.terminal_is_empty(){break}let g=grant(frame.close_demand(4096).unwrap());let units=frame.close_work_demand(4096).unwrap();let mut actual=None;let turn=frame.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual));let progress=turn.result.unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,progress.retained_capacity_bytes)}}assert!(frame.terminal_is_empty());drop(frame);let text=output.take().expect("actual decoded owner was published");assert_eq!(text.borrow().unwrap().chars().collect::<String>(),"Grüße");assert_eq!(text.allocated_bytes(),control.owned_bytes());close_text(text);drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());close_source(original);
}

struct InterruptedText{body:String,attempts:std::sync::atomic::AtomicUsize}
impl value::paged_text::TextReadSource for InterruptedText{
 fn byte_len(&self)->usize{self.body.len()}
 fn byte_at(&self,index:usize)->Option<u8>{self.body.as_bytes().get(index).copied()}
 fn read_recorded(&self,mut reply:value::paged_text::TextSourceByteReply<'_,'_>)->value::paged_text::TextSourceByteComplete{let _=reply.performed(1).expect("original Work receipt must accept the source report");let index=reply.index();let attempt=self.attempts.fetch_add(1,std::sync::atomic::Ordering::SeqCst);let result=reply.complete(Ok(self.body.as_bytes().get(index).copied()),1);if attempt==0{std::hint::black_box(&result);panic!("original byte producer interrupted after recording its actual reply")}result}
}
impl RetireOwned for InterruptedText{
 type RetirementCursor=<(String,usize) as RetireOwned>::RetirementCursor;
 fn retirement_seed(self)->Self::RetirementCursor{(self.body,self.attempts.into_inner()).retirement_seed()}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{<(String,usize) as RetireOwned>::controlled_retirement_supported()}
}
#[test]
fn encoder_settles_recorded_byte_after_unwind_then_cancels_without_replay(){
 let original=source(InterruptedText{body:"übrige".to_owned(),attempts:std::sync::atomic::AtomicUsize::new(0)});let mut physical=OriginalConstructionAuthority::new(Physical{interrupt:false,submitted:Default::default()});let mut work=OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=value::NativeEncodeControl::new(4096,&mut callback);let mut output=None;let mut frame=PagedTextEncodeFrame::<1024>::new(&mut output,1024).unwrap();
 let mut interrupted=false;for _ in 0..100{let g=grant(frame.demand(original.borrow()).unwrap());let result=catch_unwind(AssertUnwindSafe(||physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap()));if result.is_err(){interrupted=true;break}let turn=result.unwrap().unwrap().unwrap();assert!(turn.result.is_ok())}assert!(interrupted);assert_eq!(original.borrow().get().attempts.load(std::sync::atomic::Ordering::SeqCst),1);frame.begin_close();let g=grant(frame.demand(original.borrow()).unwrap());let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();assert!(turn.result.is_ok());assert_eq!(original.borrow().get().attempts.load(std::sync::atomic::Ordering::SeqCst),1);
 let mut scalar_retired=false;for _ in 0..10000{if frame.terminal_is_empty(){break}let g=grant(frame.close_demand(4096).unwrap());let units=frame.close_work_demand(4096).unwrap();let mut actual=None;let turn=frame.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual));let work=turn.work;let progress=turn.result.unwrap().progress();if progress.copied_bytes==1{assert_eq!(work,1);scalar_retired=true}if let Some(actual)=actual{assert_eq!(actual,progress.retained_capacity_bytes)}}assert!(scalar_retired,"original partial UTF8 scalar must be explicitly retired");assert!(frame.terminal_is_empty());drop(frame);assert!(output.is_none());drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());close_source(original);
}
