struct ChangedText{body:Vec<u8>,attempts:std::sync::atomic::AtomicUsize}
impl value::paged_text::TextReadSource for ChangedText{
 fn byte_len(&self)->usize{self.body.len()}
 fn byte_at(&self,index:usize)->Option<u8>{let turn=self.attempts.fetch_add(1,std::sync::atomic::Ordering::SeqCst);if turn>=self.body.len(){Some(255)}else{self.body.get(index).copied()}}
}
impl RetireOwned for ChangedText{
 type RetirementCursor=<(Vec<u8>,usize) as RetireOwned>::RetirementCursor;
 fn retirement_seed(self)->Self::RetirementCursor{(self.body,self.attempts.into_inner()).retirement_seed()}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{<(Vec<u8>,usize) as RetireOwned>::controlled_retirement_supported()}
}
#[test]
fn changed_second_pass_cannot_publish_invalid_utf8(){
 let original=source(ChangedText{body:b"ok".to_vec(),attempts:std::sync::atomic::AtomicUsize::new(0)});let mut physical=OriginalConstructionAuthority::new(Physical{interrupt:false,submitted:Default::default()});let mut work=OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=value::NativeEncodeControl::new(4096,&mut callback);let mut output=None;let mut frame=PagedTextEncodeFrame::<1024>::new(&mut output,1024).unwrap();
 let mut refused=false;for _ in 0..100{let g=grant(frame.demand(original.borrow()).unwrap());let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();match turn.result{Err(failure)=>{assert_eq!(failure.cause.primary.as_ref().unwrap().kind,value::ValueRefusalKind::InvalidValue);refused=true;break},Ok(PagedTextReadStep::Progress(_)|PagedTextReadStep::Pending)=>{},_=>panic!("changed source gained a complete UTF8 owner")}}assert!(refused);frame.begin_close();for _ in 0..10000{if frame.terminal_is_empty(){break}let g=grant(frame.close_demand(4096).unwrap());let units=frame.close_work_demand(4096).unwrap();let mut actual=None;let turn=frame.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual));let progress=turn.result.unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,progress.retained_capacity_bytes)}}assert!(frame.terminal_is_empty());drop(frame);assert!(output.is_none());drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());close_source(original);
}

struct RefusingText{address:std::sync::atomic::AtomicUsize,attempts:std::sync::atomic::AtomicUsize,reported:u64,error:std::sync::Mutex<Option<ValueError>>}
impl value::paged_text::TextReadSource for RefusingText{
 fn byte_len(&self)->usize{1}
 fn byte_at(&self,_:usize)->Option<u8>{None}
 fn read_recorded(&self,mut reply:value::paged_text::TextSourceByteReply<'_,'_>)->value::paged_text::TextSourceByteComplete{let _=reply.performed(self.reported).expect("original Work receipt must accept the source report");self.attempts.fetch_add(1,std::sync::atomic::Ordering::SeqCst);assert_eq!(reply.index(),0);let error=self.error.lock().unwrap().take().expect("original source error already transferred");self.address.store(error.message.as_ptr()as usize,std::sync::atomic::Ordering::SeqCst);let done=reply.complete(Err(error),self.reported);std::hint::black_box(&done);panic!("actual source error recorded before interruption")}
}
impl RetireOwned for RefusingText{
 type RetirementCursor=<(usize,usize,u64,Option<ValueError>) as RetireOwned>::RetirementCursor;
 fn retirement_ready(&self)->bool{self.error.lock().ok().is_some_and(|error|error.retirement_ready())}
 fn retirement_seed(self)->Self::RetirementCursor{(self.address.into_inner(),self.attempts.into_inner(),self.reported,self.error.into_inner().unwrap_or_else(|error|error.into_inner())).retirement_seed()}
 fn retirement_birth_bytes(&self)->Option<usize>{self.retirement_ready().then_some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{<(usize,usize,u64,Option<ValueError>) as RetireOwned>::controlled_retirement_supported()}
}

#[test]
fn interrupted_source_error_retains_the_same_owned_message(){
 let original=source(RefusingText{address:std::sync::atomic::AtomicUsize::new(0),attempts:std::sync::atomic::AtomicUsize::new(0),reported:1,error:std::sync::Mutex::new(Some(ValueError::new(value::ValueRefusalKind::Canceled,"actual-source-refusal-0".to_owned())))});let mut physical=OriginalConstructionAuthority::new(Physical{interrupt:false,submitted:Default::default()});let mut work=OriginalWorkAuthority::new(Work);let mut callback=|_|true;let mut control=value::NativeEncodeControl::new(4096,&mut callback);let mut output=None;let mut frame=PagedTextEncodeFrame::<1024>::new(&mut output,1024).unwrap();
 let mut interrupted=false;for _ in 0..100{let g=grant(frame.demand(original.borrow()).unwrap());let result=catch_unwind(AssertUnwindSafe(||physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap()));if result.is_err(){interrupted=true;break}assert!(result.unwrap().unwrap().unwrap().result.is_ok())}assert!(interrupted);let address=original.borrow().get().address.load(std::sync::atomic::Ordering::SeqCst);assert_ne!(address,0);let g=grant(frame.demand(original.borrow()).unwrap());let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|control.with_work_recipient(work_loan,|control|control.with_construction_recipient(loan,|control|Ok::<_,ValueError>(frame.advance(original.borrow(),control,g)))))).unwrap().unwrap().unwrap();let failure=match turn.result{Err(failure)=>failure,_=>panic!("actual source refusal was lost")};let original_error=failure.cause.primary.as_ref().expect("original error preserved");assert_eq!(original_error.kind,value::ValueRefusalKind::Canceled);assert_eq!(original_error.message.as_ptr()as usize,address);assert_eq!(original.borrow().get().attempts.load(std::sync::atomic::Ordering::SeqCst),1);close_encode_failure(failure);
 frame.begin_close();for _ in 0..10000{if frame.terminal_is_empty(){break}let g=grant(frame.close_demand(4096).unwrap());let units=frame.close_work_demand(4096).unwrap();let mut actual=None;let turn=frame.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual));let progress=turn.result.unwrap().progress();if let Some(actual)=actual{assert_eq!(actual,progress.retained_capacity_bytes)}}assert!(frame.terminal_is_empty());drop(frame);assert!(output.is_none());drop(control);assert!(!work.has_live_actions());assert!(work.into_recipient().is_ok());assert!(physical.into_recipient().is_ok());close_source(original);
}


